--- a/core/src/main/java/com/alibaba/fastjson2/JSON.java
+++ b/core/src/main/java/com/alibaba/fastjson2/JSON.java
@@ -4321,3 +4321,29 @@ public interface JSON {
         }
     }
 }
+
+    /**
+     * Parses the json string as a specified type.
+     * Returns {@code null} if received {@link String} is {@code null} or empty.
+     *
+     * @param text the specified text to be parsed
+     * @param type the specified type to parse into
+     * @param context the JSONReader context
+     * @return the parsed object of the specified type or null
+     * @throws JSONException If a parsing error occurs
+     */
+    static <T> T parseObject(String text, Type type, JSONReader.Context context) {
+        if (text == null || text.isEmpty()) {
+            return null;
+        }
+
+        ObjectReaderProvider provider = JSONFactory.getDefaultObjectReaderProvider();
+        try (JSONReader reader = JSONReader.of(text, context)) {
+            ObjectReader<T> objectReader = provider.getObjectReader(type);
+            T object = objectReader.readObject(reader, null, null, 0);
+            if (reader.ch != EOI && (context.features & IgnoreCheckClose.mask) == 0) {
+                throw new JSONException(reader.info("input not end"));
+            }
+            return object;
+        }
+    }

