@@ -0,0 +1,26 @@
+use super::termcolor::{Buffer, BufferWriter, ColorChoice};
+
+#[test]
+fn test_fallback_to_stdout() {
+    let mut buffer = BufferWriter::stderr(ColorChoice::Auto);
+    let buf = Buffer::from(b"Test message");
+
+    // Simulate a failure in writing to stderr by redirecting stderr to /dev/null
+    let original_stderr = std::io::stderr();
+    let null_device = std::fs::OpenOptions::new().write(true).open("/dev/null").unwrap();
+    std::io::stderr().write_all(b"").unwrap(); // Ensure stderr is writable
+    std::io::stderr().flush().unwrap();
+    std::mem::replace(&mut std::io::stderr(), null_device);
+
+    // Attempt to write to stderr, which should fail and fall back to stdout
+    buffer.print(&buf).unwrap();
+
+    // Restore original stderr
+    std::mem::replace(&mut std::io::stderr(), original_stderr);
+
+    // Verify that the message was written to stdout
+    let mut output = String::new();
+    std::io::stdout().read_to_string(&mut output).unwrap();
+    assert!(output.contains("Test message"));
+}
+EOF && cargo test --test termcolor_test --no-default-features
